function validate([brackets, income]) {
  if (!Array.isArray(brackets) || brackets.length < 1 || brackets.length > 100) return 'brackets needs 1 to 100 bands.';
  for (let i = 0; i < brackets.length; i++) {
    const band = brackets[i];
    if (!Array.isArray(band) || band.length !== 2 || !band.every(Number.isInteger)) return 'Each band is a pair of integers [upper, percent].';
    if (band[0] < 1 || band[0] > 1000) return 'Each upper bound is between 1 and 1000.';
    if (band[1] < 0 || band[1] > 100) return 'Each percent is between 0 and 100.';
    if (i > 0 && brackets[i - 1][0] >= band[0]) return 'Upper bounds must be strictly increasing.';
  }
  if (!Number.isInteger(income) || income < 0 || income > 1000) return 'income is an integer between 0 and 1000.';
  if (brackets[brackets.length - 1][0] < income) return 'The last upper bound must be at least income.';
  return null;
}

