function calculateTax(brackets, income) {
  let tax = 0;
  let prev = 0;
  for (const [upper, percent] of brackets) {
    const taxable = Math.min(income, upper) - prev;
    if (taxable <= 0) {
      break;
    }
    tax += taxable * percent / 100;
    prev = upper;
  }
  return tax;
}

