function calculateTax(brackets, income) {
  // Charge one dollar at a time, at the rate of the first band whose upper bound reaches it.
  let total = 0;
  for (let dollar = 1; dollar <= income; dollar++) {
    const band = brackets.find(([upper]) => upper >= dollar);
    total += band[1] / 100;
  }
  return total;
}

