function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const maxUpper = size === 'large' ? 1000 : 4 + Math.floor(rand() * 20);
  const pool = Array.from({ length: maxUpper }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const uppers = pool.slice(0, Math.min(n, maxUpper)).sort((a, b) => a - b);
  const brackets = uppers.map(upper => [upper, Math.floor(rand() * 101)]);
  const last = uppers[uppers.length - 1];
  const income = rand() < 0.2 ? last : Math.floor(rand() * (last + 1));
  return [brackets, income];
}
